"use client";

import * as React from "react";
import { CircleCheck, Ban } from "lucide-react";
import { DataTable, type Column } from "@/components/ui/DataTable";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { SuspendUserButton } from "@/components/admin/SuspendUserButton";
import { t } from "@/lib/i18n";

export interface AdminUserRow {
  id: string;
  name: string;
  email: string;
  role: "customer" | "provider" | "admin";
  suspended: boolean;
}

const ROLE_LABEL: Record<AdminUserRow["role"], "admin.roleCustomer" | "admin.roleProvider" | "admin.roleAdmin"> = {
  customer: "admin.roleCustomer",
  provider: "admin.roleProvider",
  admin: "admin.roleAdmin",
};

export function UsersTable({ rows }: { rows: AdminUserRow[] }) {
  const columns: Column<AdminUserRow>[] = [
    { key: "name", header: t("admin.colName"), sortable: true },
    { key: "email", header: t("admin.colEmail") },
    {
      key: "role",
      header: t("admin.colRole"),
      sortable: true,
      render: (r) => t(ROLE_LABEL[r.role]),
    },
    {
      key: "suspended",
      header: t("admin.colState"),
      render: (r) =>
        r.suspended ? (
          <StatusBadge tone="alert" icon={Ban}>
            {t("admin.stateSuspended")}
          </StatusBadge>
        ) : (
          <StatusBadge tone="success" icon={CircleCheck}>
            {t("admin.stateActive")}
          </StatusBadge>
        ),
    },
    {
      key: "action",
      header: t("admin.colAction"),
      render: (r) =>
        r.role === "admin" ? (
          <span className="text-ink-soft">—</span>
        ) : (
          <SuspendUserButton userId={r.id} name={r.name} suspended={r.suspended} />
        ),
    },
  ];

  return (
    <DataTable
      caption={t("admin.usersCaption")}
      columns={columns}
      rows={rows}
      getRowKey={(r) => r.id}
      emptyText={t("admin.usersNone")}
    />
  );
}

