import * as React from "react";
import { useTransition } from "react";
import { Check, Ban, ShieldAlert } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { resolveReport, setUserSuspended } from "@/app/(admin)/admin/actions";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

export interface ReportItem {
  id: string;
  reason: string;
  status: "open" | "reviewed";
  whenLabel: string;
  reporterName: string;
  targetId: string | null;
  targetName: string | null;
}

export function ReportCard({ report }: { report: ReportItem }) {
  const [pending, startTransition] = useTransition();
  const { announce, toast } = useToast();

  function review() {
    startTransition(async () => {
      const res = await resolveReport(report.id);
      if (!res.ok) {
        toast(t("admin.decisionError"), "alert");
        return;
      }
      announce(t("admin.reportReviewed"), true);
    });
  }

  function suspendTarget() {
    if (!report.targetId) return;
    startTransition(async () => {
      const res = await setUserSuspended({
        userId: report.targetId!,
        suspended: true,
      });
      if (!res.ok) {
        toast(t("admin.decisionError"), "alert");
        return;
      }
      announce(
        t("admin.userSuspended", { name: report.targetName ?? "user" }),
        true,
      );
    });
  }

  return (
    <Card as="li" className="flex flex-col gap-3">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <span className="flex items-center gap-2 text-base font-bold text-ink">
          <ShieldAlert size={18} strokeWidth={2} aria-hidden="true" className="text-alert" />
          {t("admin.reportReporter")}: {report.reporterName}
          {report.targetName ? (
            <span className="text-ink-soft">
              {" · "}
              {t("admin.reportTarget")}: {report.targetName}
            </span>
          ) : null}
        </span>
        <StatusBadge tone={report.status === "open" ? "warning" : "success"}>
          {report.status === "open"
            ? t("admin.reportStatusOpen")
            : t("admin.reportStatusReviewed")}
        </StatusBadge>
      </div>

      <p className="text-base text-ink">{report.reason}</p>
      <p className="text-sm text-ink-soft">
        {t("admin.reportWhen")}: {report.whenLabel}
      </p>

      <div className="flex flex-wrap gap-3 border-t border-border pt-3">
        {report.status === "open" ? (
          <Button icon={Check} onClick={review} disabled={pending}>
            {t("admin.reportReview")}
          </Button>
        ) : null}
        {report.targetId ? (
          <Button
            variant="danger"
            icon={Ban}
            onClick={suspendTarget}
            disabled={pending}
          >
            {t("admin.reportSuspendTarget")}
          </Button>
        ) : null}
      </div>
    </Card>
  );
}
