import * as React from "react";
import { useTransition } from "react";
import { Ban, RotateCcw } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { setUserSuspended } from "@/app/(admin)/admin/actions";
import { t } from "@/lib/i18n";
import { useToast } from "@/components/ui/Toast";

export function SuspendUserButton({
  userId,
  name,
  suspended,
}: {
  userId: string;
  name: string;
  suspended: boolean;
}) {
  const [pending, startTransition] = useTransition();
  const { announce, toast } = useToast();

  function toggle() {
    const next = !suspended;
    startTransition(async () => {
      const res = await setUserSuspended({ userId, suspended: next });
      if (!res.ok) {
        toast(t("admin.decisionError"), "alert");
        return;
      }
      announce(
        next
          ? t("admin.userSuspended", { name })
          : t("admin.userReinstated", { name }),
        true,
      );
    });
  }

  return (
    <Button
      variant={suspended ? "ghost" : "danger"}
      icon={suspended ? RotateCcw : Ban}
      onClick={toggle}
      disabled={pending}
    >
      {suspended ? t("admin.reinstate") : t("admin.suspend")}
    </Button>
  );
}

